recipeCss:
:root{--background:#113B38;--surface:#1B4B47;--surface-deep:#0E3330;--field:#143F3C;--text:#F4F1E6;--muted:#BFD6CF;--accent:#F5C449;--ink:#16211F;--secondary:#A9D3C9;--line:#2C5F5A;--line-strong:#7FA9A1;--radius:10px;--radius-sm:6px;--maxw:1280px;--s14:14px;--s17:17px;--s19:19px;--s30:30px;--s48:48px;--s60:60px;--ease:cubic-bezier(0.2,0.7,0.3,1)}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--background);color:var(--text);font-family:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;font-size:var(--s17);line-height:1.6;font-variant-numeric:tabular-nums}
h1,h2,h3{font-family:'Archivo',system-ui,sans-serif;font-weight:700;letter-spacing:-0.02em;line-height:1.08;margin:0}
h1{font-size:var(--s48)}h2{font-size:var(--s30)}h3{font-size:var(--s19);line-height:1.28;letter-spacing:-0.01em}
p{margin:0 0 .9em;max-width:68ch}
a{color:var(--text);text-underline-offset:3px;text-decoration-thickness:1px}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 40px}
.site-head{display:flex;align-items:center;gap:32px;padding:14px 40px;max-width:var(--maxw);margin:0 auto}
.brand{display:flex;align-items:center;gap:10px;font-family:'Archivo',sans-serif;font-weight:700;font-size:var(--s19);letter-spacing:-0.02em;text-decoration:none;padding:4px 0}
.brand svg{width:28px;height:28px;display:block}
.head-links{display:flex;gap:26px;margin-left:4px}
.head-links a{text-decoration:none;padding:12px 2px;font-size:var(--s17)}
.head-links a:hover{text-decoration:underline;text-decoration-thickness:2px}
.head-links a:active{color:var(--secondary)}
.head-act{margin-left:auto}
.head-act a{display:inline-flex;align-items:center;min-height:44px;padding:0 18px;border:2px solid var(--line-strong);border-radius:999px;font-weight:600;text-decoration:none;font-size:var(--s14)}
.head-act a:hover{border-color:var(--text);background:var(--surface)}
.head-act a:active{background:var(--field)}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 22px;border-radius:var(--radius-sm);border:2px solid transparent;font:inherit;font-weight:600;font-size:var(--s17);cursor:pointer;transition:background-color .18s var(--ease),color .18s var(--ease),border-color .18s var(--ease),transform .12s var(--ease)}
.btn-primary{background:var(--accent);color:var(--ink);width:100%}
.btn-primary:hover{background:#FFD264}
.btn-primary:active{background:#E3B23C;transform:translateY(1px)}
.btn-primary:disabled,.btn-primary[aria-disabled='true']{background:#3B6B64;color:#CFE2DB;border-color:#7FA9A1;cursor:not-allowed}
.btn-primary[aria-disabled='true']:hover{background:#3B6B64}
html[data-state='answered'] .btn-primary[aria-disabled='true']{background:var(--accent);color:var(--ink);border-color:transparent;cursor:pointer}
html[data-state='answered'] .btn-primary[aria-disabled='true']:hover{background:#FFD264}
.btn-ghost{background:transparent;border:2px solid var(--ink);color:var(--ink);min-height:44px;padding:0 16px;font-size:var(--s14)}
.btn-ghost:hover{background:rgba(17,32,30,0.14)}
.btn-ghost:active{background:rgba(17,32,30,0.26);transform:translateY(1px)}
.field{display:block}
.field>span{display:block;font-size:var(--s14);font-weight:600;margin-bottom:6px;color:var(--muted)}
select,input[type='text'],input[type='number']{width:100%;min-height:46px;padding:0 12px;border-radius:var(--radius-sm);border:2px solid var(--line-strong);background:var(--field);color:var(--text);font:inherit;font-size:var(--s17);appearance:none}
.sel{position:relative;display:block}
.sel::after{content:'';position:absolute;right:14px;top:calc(50% + 11px);width:0;height:0;border-left:6px solid transparent;border-right:6px solid transparent;border-top:7px solid var(--secondary);transform:translateY(-50%);pointer-events:none}
select:hover,input[type='text']:hover,input[type='number']:hover{border-color:var(--text)}
select:focus,input[type='text']:focus,input[type='number']:focus,select:active,input:active{border-color:var(--accent)}
select:disabled,input:disabled{border-color:var(--line);color:#8FB3AB;cursor:not-allowed}
.first{max-width:var(--maxw);margin:0 auto;padding:6px 40px 44px;display:grid;grid-template-columns:repeat(12,1fr);gap:18px 24px}
.first>h1{grid-column:1/6;grid-row:1}
.opening{grid-column:1/6;grid-row:2;font-size:var(--s17);margin:0}
.intro-photo{grid-column:1/6;grid-row:3;margin:6px 0 0;border-radius:var(--radius);overflow:hidden;background:var(--surface)}
.intro-photo img{display:block;width:100%;height:196px;object-fit:cover}
.toolcol{grid-column:6/13;grid-row:1/4;display:grid;gap:14px;align-content:start}
.tool-card{background:var(--surface);border-radius:var(--radius);padding:22px;display:grid;gap:16px}
.tool-card h2{font-size:var(--s19);letter-spacing:-0.01em;margin:0}
.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px 14px}
.hint{margin:0;font-size:var(--s14);color:var(--muted)}
.answer{border-radius:var(--radius);padding:20px 22px 16px;background:var(--field);transition:background-color .3s var(--ease),color .3s var(--ease)}
.answer-empty{margin:0;color:var(--muted);font-size:var(--s17);max-width:44ch}
.answer-full,.answer-error{display:none}
html[data-state='answered'] .answer{background:var(--accent);color:var(--ink)}
html[data-state='answered'] .answer-empty{display:none}
html[data-state='answered'] .answer-full{display:flex;flex-direction:column}
html[data-state='error'] .answer-empty{display:none}
html[data-state='error'] .answer-error{display:block;background:var(--field)}
.answer-error p{margin:0;color:var(--text);font-size:var(--s17);max-width:52ch}
.answer-full>*{order:1}
.answer-full .result-actions{order:2}
.answer-full .tape{order:3}
.answer-label{font-size:var(--s14);font-weight:600;margin:0;color:rgba(17,32,30,0.75)}
.size{font-family:'Archivo',sans-serif;font-weight:700;font-size:var(--s60);line-height:1;margin:0 0 4px;letter-spacing:-0.03em}
.size-meta{font-size:var(--s14);margin:0 0 10px;color:rgba(17,32,30,0.8)}
.rule{font-size:var(--s17);margin:0 0 6px;max-width:46ch}
.brand-note{font-size:var(--s14);margin:0 0 12px}
.result-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap}
.result-actions a{font-size:var(--s14);color:var(--ink);padding:6px 0}
.tape{display:block;width:100%;height:auto;margin:10px 0 0}
.band{padding:60px 0}
.band-surface{background:var(--surface-deep)}
.lede{font-size:var(--s19);max-width:62ch}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:30px 32px;margin:26px 0 0}
.note h3{margin-bottom:6px}
.note p{margin:0;color:var(--muted);max-width:46ch}
.panel{background:var(--surface);border-radius:var(--radius);padding:24px;margin:26px 0 0}
.panel h3{margin-bottom:8px}
.panel p{margin:0;color:var(--muted);max-width:72ch}
.tablewrap{overflow-x:auto;border-radius:var(--radius-sm)}
table{width:100%;border-collapse:collapse;font-size:var(--s17);margin-top:16px}
caption{text-align:left;font-size:var(--s14);color:var(--muted);padding-bottom:10px}
th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line)}
thead th{font-size:var(--s14);font-weight:600;color:var(--secondary)}
tbody td:first-child{font-weight:600}
tbody tr:hover{background:var(--surface)}
figure{margin:28px 0 0}
figure img{display:block;width:100%;height:100%;object-fit:cover;border-radius:var(--radius)}
.split{display:grid;grid-template-columns:1.15fr .85fr;gap:32px;align-items:start}
.split figure{margin:0;height:100%}
.split figure img{height:100%;min-height:320px}
.faq dt{font-weight:600;margin-top:20px}
.faq dd{margin:6px 0 0;color:var(--muted);max-width:68ch}
.site-foot{background:var(--surface-deep);padding:48px 0 32px}
.foot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.foot-grid h3{font-family:'Instrument Sans',sans-serif;font-size:var(--s14);color:var(--secondary);letter-spacing:0}
.foot-grid ul{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:8px;font-size:var(--s14)}
.foot-grid a{padding:4px 0;display:inline-block}
.foot-note{font-size:var(--s14);color:var(--muted);max-width:70ch;margin:32px 0 0}
@media (max-width:900px){.wrap{padding-left:20px;padding-right:20px}.site-head{flex-wrap:nowrap;gap:10px;padding:10px 20px}.brand{font-size:var(--s17)}.head-links{margin-left:auto;gap:14px}.head-links a{font-size:15px;padding:12px 0}.head-links a[href='/']{display:none}.head-act{display:none}.first{grid-template-columns:1fr;padding:4px 20px 28px}.first>h1{grid-column:1;grid-row:1;font-size:var(--s30)}.toolcol{grid-column:1;grid-row:2}.opening{grid-column:1;grid-row:3}.intro-photo{grid-column:1;grid-row:4}.intro-photo img{height:170px}.size{font-size:38px}.size-meta,.brand-note{font-size:13px}.rule{font-size:15px;line-height:1.45}.grid3{grid-template-columns:1fr}.split{grid-template-columns:1fr}h2{font-size:24px}.foot-grid{grid-template-columns:1fr 1fr}.band{padding:40px 0}.tablewrap{border:2px solid var(--line);background:var(--surface-deep)}table{min-width:560px}}
@media (max-width:520px){.fields{gap:10px}.field>span{font-size:13px}select,input[type='text'],input[type='number']{font-size:16px;min-height:44px}.tool-card{padding:16px;gap:12px}.answer{padding:16px}}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
